import{createMachineStore,unchanged}from'./types.js';
const firstEnabledIndex=(opts)=>opts.findIndex((o)=>!o.disabled);
function lastEnabledIndex(opts){
for(let i=opts.length-1;i>=0;i-=1)
if(!opts[i].disabled)
return i;
return-1;
}
function stepEnabled(opts,from,delta,loop){
const n=opts.length;
if(n===0)
return-1;
if(from<0)
return delta>0?firstEnabledIndex(opts):lastEnabledIndex(opts);
for(let step=1;step<=n;step+=1){
const raw=from+delta*step;
if(!loop&&(raw<0||raw>=n))
return from;
const idx=((raw%n)+n)%n;
if(!opts[idx].disabled)
return idx;
}
return from;
}
function matchTypeahead(opts,ch,current,prevBuf,prevMs,nowMs,timeoutMs){
const fresh=nowMs-prevMs>timeoutMs;
const buf=(fresh?'':prevBuf)+ch.toLowerCase();
const repeat=buf.length>1&&buf.split('').every((c)=>c===buf[0]);
const query=repeat?buf[0]:buf;
const start=fresh||repeat?current+1:Math.max(0,current);
const n=opts.length;
for(let i=0;i<n;i+=1){
const idx=(start+i)%n;
const opt=opts[idx];
if(!opt.disabled&&opt.label.toLowerCase().startsWith(query)){
return{index:idx,buffer:buf};
}
}
return{index:current,buffer:buf};
}
export function createInitialListboxMenuState(options={}){
const opts=[...(options.options??[])];
const selectedId=options.initialSelectedId??null;
const selIdx=selectedId!==null?opts.findIndex((o)=>o.id===selectedId&&!o.disabled):-1;
const open=options.defaultOpen??false;
return{
options:opts,
open,
activeIndex:open?(selIdx>=0?selIdx:firstEnabledIndex(opts)):-1,
selectedId,
typeaheadBuffer:'',
lastTypeaheadMs:-Infinity,
};
}
export function reduceListboxMenu(state,event,loop=false,timeoutMs=500){
const opts=state.options;
const selIdx=state.selectedId!==null?opts.findIndex((o)=>o.id===state.selectedId&&!o.disabled):-1;
switch(event.type){
case'OPEN':{
if(state.open)
return unchanged(state,event);
const activeIndex=selIdx>=0?selIdx:firstEnabledIndex(opts);
return{
prev:state,
next:{...state,open:true,activeIndex,typeaheadBuffer:''},
event,
changed:true,
direction:1,
anchorRect:event.anchorRect,
};
}
case'CLOSE':{
if(!state.open)
return unchanged(state,event);
return{prev:state,next:{...state,open:false,activeIndex:-1,typeaheadBuffer:''},event,changed:true,direction:-1};
}
case'TOGGLE':{
return state.open
?reduceListboxMenu(state,{type:'CLOSE'},loop,timeoutMs)
:reduceListboxMenu(state,{type:'OPEN',anchorRect:event.anchorRect},loop,timeoutMs);
}
case'HIGHLIGHT':{
if(event.index<-1||event.index>=opts.length)
return unchanged(state,event);
if(event.index>=0&&opts[event.index].disabled)
return unchanged(state,event);
if(event.index===state.activeIndex)
return unchanged(state,event);
const direction=(state.activeIndex>=0&&event.index>=0?Math.sign(event.index-state.activeIndex):0);
return{prev:state,next:{...state,activeIndex:event.index},event,changed:true,direction};
}
case'SELECT':{
const idx=opts.findIndex((o)=>o.id===event.id&&!o.disabled);
if(idx===-1)
return unchanged(state,event);
return{
prev:state,
next:{...state,open:false,activeIndex:-1,selectedId:event.id,typeaheadBuffer:''},
event,
changed:true,
direction:0,
haptic:'selection',
announcement:opts[idx].label,
};
}
case'SET_OPTIONS':{
return{prev:state,next:{...state,options:[...event.options]},event,changed:true,direction:0};
}
case'KEY_DOWN':{
const k=event.key;
const nowMs=event.timeMs??0;
if(k==='Escape'){
if(!state.open)
return unchanged(state,event);
return{prev:state,next:{...state,open:false,activeIndex:-1,typeaheadBuffer:''},event,changed:true,direction:-1};
}
if(k==='ArrowDown'||k==='ArrowUp'||k==='Home'||k==='End'){
const nextActive=!state.open
?k==='End'||(k==='ArrowUp'&&selIdx<0)
?lastEnabledIndex(opts)
:selIdx>=0&&k!=='Home'
?selIdx
:firstEnabledIndex(opts)
:k==='Home'
?firstEnabledIndex(opts)
:k==='End'
?lastEnabledIndex(opts)
:stepEnabled(opts,state.activeIndex,k==='ArrowDown'?1:-1,loop);
if(state.open&&nextActive===state.activeIndex)
return unchanged(state,event);
const direction=(!state.open?1:Math.sign(nextActive-state.activeIndex)||0);
return{prev:state,next:{...state,open:true,activeIndex:nextActive},event,changed:true,direction};
}
if(k==='Enter'||(k===' '&&(state.typeaheadBuffer===''||nowMs-state.lastTypeaheadMs>timeoutMs))){
if(!state.open){
const activeIndex=selIdx>=0?selIdx:firstEnabledIndex(opts);
return{prev:state,next:{...state,open:true,activeIndex},event,changed:true,direction:1};
}
const chosen=state.activeIndex>=0?opts[state.activeIndex]:undefined;
if(!chosen||chosen.disabled)
return unchanged(state,event);
return{
prev:state,
next:{...state,open:false,activeIndex:-1,selectedId:chosen.id,typeaheadBuffer:''},
event,
changed:true,
direction:0,
haptic:'selection',
announcement:chosen.label,
};
}
if(k.length===1&&k.trim().length>=0){
if(k===' '&&state.typeaheadBuffer==='')
return unchanged(state,event);
const{index,buffer}=matchTypeahead(opts,k,state.activeIndex,state.typeaheadBuffer,state.lastTypeaheadMs,nowMs,timeoutMs);
if(index<0||(index===state.activeIndex&&buffer===state.typeaheadBuffer))
return unchanged(state,event);
const direction=(state.activeIndex>=0?Math.sign(index-state.activeIndex)||0:1);
return{
prev:state,
next:{...state,open:true,activeIndex:index,typeaheadBuffer:buffer,lastTypeaheadMs:nowMs},
event,
changed:true,
direction,
};
}
return unchanged(state,event);
}
}
}
export function createListboxMenuMachine(options={}){
const loop=options.loop??false;
const timeoutMs=options.typeaheadTimeoutMs??500;
return createMachineStore(createInitialListboxMenuState(options),(state,event)=>reduceListboxMenu(state,event,loop,timeoutMs));
}
